// Jessie â Envoy Mirror  (Code node, Run Once for All Items)
//
// Copies Envoy-origin bookings from the room RESOURCE calendars onto the KDC
// Bookings calendar, so they appear on the master view AND Jessie (which reads
// KDC Bookings) can see them. Idempotent + self-healing: each run reconciles â
// create new copies, update changed ones, delete copies whose source is gone.
//
// UNTESTED SCAFFOLD â drafted with no live pull/test (docs/design/envoy-mirror-build.md).
// DEPENDENCY TO VERIFY FIRST: this node calls the Google Calendar API with
// this.helpers.httpRequestWithAuthentication + the 'googleCalendarOAuth2Api'
// credential. If that helper is not usable from a Code node in the installed
// n8n, build the Google calls as HTTP Request nodes instead (same logic).
if (!this || !this.helpers || typeof this.helpers.httpRequestWithAuthentication !== 'function') {
  throw new Error('httpRequestWithAuthentication not available in this Code node â build the Google calls as HTTP Request nodes (see docs/design/envoy-mirror-build.md).');
}

const KDC = 'c_re5mcrg9om0macp9doqhlsi83g@group.calendar.google.com';

// Room -> resource calendar. Studio E uses the LIVE id; the workflows' old
// c_18807te... is dead (docs/design/studio-e-id-fix.md).
const ROOMS = {
  'Studio 1':'hitproductions.net_3737303833303637363538@resource.calendar.google.com',
  'Studio 2':'c_18871bprki2umhrkjc4qcaldse1f8@resource.calendar.google.com',
  'Studio 3':'c_1886me03bdcrki5bhu8vddknl472k@resource.calendar.google.com',
  'Studio 4':'c_188e94dapvbp8jvrjmuga6qbof826@resource.calendar.google.com',
  'Studio 5':'c_18889v3glj9cqiotg8j95jaqmdhmm@resource.calendar.google.com',
  'Studio 6':'c_18838qt2ru30ein7gcefjiarplkre@resource.calendar.google.com',
  'Studio 7':'c_188dupcj6cqfaipohqffj07ruq8de@resource.calendar.google.com',
  'Studio 8':'c_18863v8hd6f42isegdh9i30psuo9q@resource.calendar.google.com',
  'Studio A':'c_18843dclutqm6hl9nbeg002phapfu@resource.calendar.google.com',
  'Studio B':'c_1881vgb66tkpujjelnn3rniugd9pk@resource.calendar.google.com',
  'Studio C':'c_188797f37eu9ujs6ldpf3smn78joc@resource.calendar.google.com',
  'Studio D':'c_18801gc6ck77gho7jl0e1fug94u92@resource.calendar.google.com',
  'Studio E':'c_1888r4bbc2lhqgndmprism70nft64@resource.calendar.google.com',
  'Studio F':'c_188em7d58podeju3i8q6juqlufkls@resource.calendar.google.com',
  'Studio M':'c_1885k4adm87fqjd2j3j2usqftph5c@resource.calendar.google.com',
  'M1':'c_1889v46vd62fkjk3i7r1hsfem7tcm@resource.calendar.google.com',
  'M2':'c_1883ui6lnfc9ogt2hrmg57a30n72q@resource.calendar.google.com',
  'M3':'c_188d7dkqgnfs6hu4iunlu5ogftct0@resource.calendar.google.com',
  'M4':'c_18869nhmsj2uki8mljoi48v1cj7l4@resource.calendar.google.com',
  'M5':'c_1889h30ci9noqjcbnoogad9qk75vq@resource.calendar.google.com',
  'M6':'c_188f9gnq0a9tehf4g9ja57l83c0ts@resource.calendar.google.com',
  'M7':'c_1880r9hhk9c2agpbko87o7fojosh0@resource.calendar.google.com',
  'M8':'c_1884cu2cc84iujsjnu03s21f0ct9q@resource.calendar.google.com',
  'Salin':'c_1887hh5rsv6q4gt8hnu6ered170lg@resource.calendar.google.com',
  'Katha':'c_1881169pcpn12gsnm6i7sc0gjk7gk@resource.calendar.google.com',
  'Likha':'c_1886t6cjgrq0ihgpime01uibcqsg6@resource.calendar.google.com',
  'Lobby':'c_188227mpeagjuhi7gqlgns1di14be@resource.calendar.google.com'
};

const api = (opts) =>
  this.helpers.httpRequestWithAuthentication.call(this, 'googleCalendarOAuth2Api',
    Object.assign({ json: true }, opts));

const evUrl = (cal) =>
  'https://www.googleapis.com/calendar/v3/calendars/' + encodeURIComponent(cal) + '/events';

const now = Date.now();
const timeMin = new Date(now - 24 * 3600 * 1000).toISOString();       // small past buffer
const timeMax = new Date(now + 90 * 24 * 3600 * 1000).toISOString();  // forward window
const isoOf = (x) => (x && (x.dateTime || x.date)) || '';

// Narrow scope: only mirror EnvoyORIGIN events. Jessie's own bookings on a
// resource calendar are organized by KDC Bookings (excluded); personal-calendar
// bookings are organized by a person and carry no Envoy marker (excluded).
const isEnvoy = (ev, calId) => {
  const desc = String(ev.description || '');
  const org = String((ev.organizer || {}).email || '').toLowerCase();
  return /created by envoy/i.test(desc)
      || /^rooms/.test(String(ev.id || ''))
      || org === String(calId).toLowerCase();
};

// 1) Desired mirror set, from the resource calendars.
const desired = {};   // sourceKey -> { room, summary, start, end }
for (const room of Object.keys(ROOMS)) {
  const calId = ROOMS[room];
  let res;
  try {
    res = await api({ method: 'GET', url: evUrl(calId),
      qs: { timeMin, timeMax, singleEvents: 'true', orderBy: 'startTime', maxResults: 250 } });
  } catch (e) { continue; }   // skip a calendar that errors; next run retries
  for (const ev of ((res && res.items) || [])) {
    if (!ev || ev.status === 'cancelled') continue;
    if (!isEnvoy(ev, calId)) continue;
    desired[calId + ':' + ev.id] = { room, summary: ev.summary || 'Envoy booking',
      start: ev.start, end: ev.end };
  }
}

// 2) Existing mirror copies on KDC Bookings (marked with a private property).
const existing = {};   // sourceKey -> { id, summary, startISO, endISO }
let pageToken;
do {
  let res;
  try {
    res = await api({ method: 'GET', url: evUrl(KDC),
      qs: Object.assign({ timeMin, timeMax, singleEvents: 'true', maxResults: 250,
        privateExtendedProperty: 'envoyMirror=1' }, pageToken ? { pageToken } : {}) });
  } catch (e) { break; }
  for (const ev of ((res && res.items) || [])) {
    const sk = ev.extendedProperties && ev.extendedProperties.private
      && ev.extendedProperties.private.envoyMirrorSource;
    if (!sk) continue;
    existing[sk] = { id: ev.id, summary: ev.summary || '',
      startISO: isoOf(ev.start), endISO: isoOf(ev.end) };
  }
  pageToken = res && res.nextPageToken;
} while (pageToken);

const bodyFor = (d, sourceKey) => ({
  summary: d.room + ' - ' + d.summary,
  location: d.room,
  description: 'Created by Envoy (mirrored). Manage this booking in Envoy.\nsource: ' + sourceKey,
  start: d.start,
  end: d.end,
  transparency: 'opaque',
  reminders: { useDefault: false },
  extendedProperties: { private: { envoyMirror: '1', envoyMirrorSource: sourceKey } }
});

let created = 0, updated = 0, deleted = 0, failed = 0;

// 3a) Create new / update changed.
for (const sourceKey of Object.keys(desired)) {
  const d = desired[sourceKey], ex = existing[sourceKey];
  try {
    if (!ex) {
      await api({ method: 'POST', url: evUrl(KDC), body: bodyFor(d, sourceKey) });
      created++;
    } else if (ex.summary !== (d.room + ' - ' + d.summary)
            || ex.startISO !== isoOf(d.start) || ex.endISO !== isoOf(d.end)) {
      await api({ method: 'PATCH', url: evUrl(KDC) + '/' + encodeURIComponent(ex.id),
        body: bodyFor(d, sourceKey) });
      updated++;
    }
  } catch (e) { failed++; }
}

// 3b) Delete copies whose source is gone (Envoy booking cancelled/released).
for (const sourceKey of Object.keys(existing)) {
  if (desired[sourceKey]) continue;
  try {
    await api({ method: 'DELETE', url: evUrl(KDC) + '/' + encodeURIComponent(existing[sourceKey].id) });
    deleted++;
  } catch (e) { failed++; }
}

return [{ json: { ran: new Date().toISOString(), resourceCalendars: Object.keys(ROOMS).length,
  desired: Object.keys(desired).length, existing: Object.keys(existing).length,
  created, updated, deleted, failed } }];
